{
  "pdf_page": 80,
  "book_page": 50,
  "verified_by": "claude-opus-5",
  "verified_on": "2026-09-05",
  "entries": [
    {
      "entry": 0,
      "root": "Bhâ 2",
      "verdict": "plausible",
